arguments.content:
locals {
  ingress_cidr = "10.10.0.0/20"
  private_cidr = "10.10.32.0/20"
  labels       = { "mediapulse_deployment" = local.prefix }
}

resource "google_compute_network" "vpc" {
  name                    = "${local.prefix}-vpc"
  auto_create_subnetworks = false
  project                 = local.project
  labels                  = local.labels
}

resource "google_compute_subnetwork" "ingress" {
  name                     = "${local.prefix}-ingress-subnet"
  project                  = local.project
  region                   = local.region
  network                  = google_compute_network.vpc.id
  ip_cidr_range            = local.ingress_cidr
  private_ip_google_access = false
  labels                   = local.labels
}

resource "google_compute_subnetwork" "private" {
  name                     = "${local.prefix}-private-subnet"
  project                  = local.project
  region                   = local.region
  network                  = google_compute_network.vpc.id
  ip_cidr_range            = local.private_cidr
  private_ip_google_access = true
  labels                   = local.labels
}

resource "google_compute_firewall" "ingress_http" {
  name    = "${local.prefix}-allow-http"
  project = local.project
  network = google_compute_network.vpc.id
  labels  = local.labels

  allow {
    protocol = "tcp"
    ports    = ["80", "8080"]
  }
  source_ranges = ["0.0.0.0/0"]
  target_tags   = ["mediapulse-ingress", "mediapulse-api"]
}

resource "google_compute_firewall" "db_internal" {
  name    = "${local.prefix}-allow-db-internal"
  project = local.project
  network = google_compute_network.vpc.id
  labels  = local.labels

  allow {
    protocol = "tcp"
    ports    = ["5432"]
  }
  source_ranges = [local.ingress_cidr, local.private_cidr]
  target_tags   = ["mediapulse-db"]
}

# VPC Private Service Access range for Cloud SQL private IP
resource "google_compute_global_address" "psa_range" {
  name          = "${local.prefix}-psa-range"
  project       = local.project
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 20
  network       = google_compute_network.vpc.id
  labels        = local.labels
}

resource "google_service_networking_connection" "psa" {
  provider                 = google-beta
  network                  = google_compute_network.vpc.id
  service                  = "servicenetworking.googleapis.com"
  reserved_peering_ranges  = [google_compute_global_address.psa_range.name]
}

resource "google_kms_key_ring" "kr" {
  name     = "${local.prefix}-keyring"
  project  = local.project
  location = local.region
  labels   = local.labels
}

resource "google_kms_crypto_key" "database" {
  name            = "${local.prefix}-database-key"
  key_ring        = google_kms_key_ring.kr.id
  rotation_period = "7776000s"
  labels          = local.labels
}

resource "google_kms_crypto_key" "messaging" {
  name            = "${local.prefix}-messaging-key"
  key_ring        = google_kms_key_ring.kr.id
  rotation_period = "7776000s"
  labels          = local.labels
}

resource "google_kms_crypto_key" "projection" {
  name            = "${local.prefix}-projection-key"
  key_ring        = google_kms_key_ring.kr.id
  rotation_period = "7776000s"
  labels          = local.labels
}

resource "google_kms_crypto_key" "audit" {
  name            = "${local.prefix}-audit-key"
  key_ring        = google_kms_key_ring.kr.id
  rotation_period = "7776000s"
  labels          = local.labels
}

locals {
  sa_labels = local.labels
}

resource "google_service_account" "api" {
  account_id   = "${local.prefix}-api"
  display_name = "MediaPulse API Cloud Run"
  project      = local.project
  labels       = local.sa_labels
}

resource "google_service_account" "processor" {
  account_id   = "${local.prefix}-processor"
  display_name = "MediaPulse Processor Function"
  project      = local.project
  labels       = local.sa_labels
}

resource "google_service_account" "relay" {
  account_id   = "${local.prefix}-relay"
  display_name = "MediaPulse Outbox Relay Function"
  project      = local.project
  labels       = local.sa_labels
}

resource "google_service_account" "archiver" {
  account_id   = "${local.prefix}-archiver"
  display_name = "MediaPulse Audit Archiver Function"
  project      = local.project
  labels       = local.sa_labels
}

resource "google_service_account" "scheduler" {
  account_id   = "${local.prefix}-scheduler"
  display_name = "MediaPulse Scheduler Invoker"
  project      = local.project
  labels       = local.sa_labels
}

# Project-level role bindings
resource "google_project_iam_member" "api_cloudsql_client" {
  project = local.project
  role    = "roles/cloudsql.client"
  member  = "serviceAccount:${google_service_account.api.email}"
}

resource "google_project_iam_member" "api_datastore_viewer" {
  project = local.project
  role    = "roles/datastore.viewer"
  member  = "serviceAccount:${google_service_account.api.email}"
}

resource "google_project_iam_member" "api_pubsub_publisher" {
  project = local.project
  role    = "roles/pubsub.publisher"
  member  = "serviceAccount:${google_service_account.api.email}"
}

resource "google_project_iam_member" "processor_datastore_user" {
  project = local.project
  role    = "roles/datastore.user"
  member  = "serviceAccount:${google_service_account.processor.email}"
}

resource "google_project_iam_member" "relay_cloudsql_client" {
  project = local.project
  role    = "roles/cloudsql.client"
  member  = "serviceAccount:${google_service_account.relay.email}"
}

resource "google_project_iam_member" "relay_pubsub_publisher" {
  project = local.project
  role    = "roles/pubsub.publisher"
  member  = "serviceAccount:${google_service_account.relay.email}"
}

resource "google_project_iam_member" "archiver_cloudsql_client" {
  project = local.project
  role    = "roles/cloudsql.client"
  member  = "serviceAccount:${google_service_account.archiver.email}"
}

resource "google_project_iam_member" "api_kms" {
  project = local.project
  role    = "roles/cloudkms.cryptoKeyEncrypterDecrypter"
  member  = "serviceAccount:${google_service_account.api.email}"
}

resource "google_project_iam_member" "relay_kms" {
  project = local.project
  role    = "roles/cloudkms.cryptoKeyEncrypterDecrypter"
  member  = "serviceAccount:${google_service_account.relay.email}"
}

resource "google_project_iam_member" "archiver_kms" {
  project = local.project
  role    = "roles/cloudkms.cryptoKeyEncrypterDecrypter"
  member  = "serviceAccount:${google_service_account.archiver.email}"
}

resource "google_project_iam_member" "processor_kms" {
  project = local.project
  role    = "roles/cloudkms.cryptoKeyEncrypterDecrypter"
  member  = "serviceAccount:${google_service_account.processor.email}"
}

resource "google_sql_database_instance" "main" {
  name                = "${local.prefix}-db"
  project             = local.project
  region              = local.region
  database_version    = "POSTGRES_15"
  deletion_protection = false
  encryption_key_name  = google_kms_crypto_key.database.id

  settings {
    tier              = "db-custom-2-4096"
    availability_type = "ZONAL"
    labels            = local.labels

    ip_configuration {
      ipv4_enabled = false
      private_network = google_compute_network.vpc.self_link
    }

    disk_encryption_configuration {
      kms_key_name = google_kms_crypto_key.database.id
    }
  }

  depends_on = [google_service_networking_connection.psa]
}

resource "google_sql_database" "db" {
  name     = local.db_name
  project  = local.project
  instance = google_sql_database_instance.main.name
}

resource "google_sql_user" "user" {
  name     = local.db_user
  project  = local.project
  instance = google_sql_database_instance.main.name
  password = local.db_pass
}

locals {
  db_host   = google_sql_database_instance.main.private_ip_address
  db_url    = "postgresql://${local.db_user}:${urlencode(local.db_pass)}@${local.db_host}:5432/${local.db_name}?sslmode=disable"
}

resource "google_secret_manager_secret" "db_url" {
  secret_id = "${local.prefix}-db-url"
  project   = local.project
  labels    = local.labels

  replication {
    auto {}
  }
}

resource "google_secret_manager_secret_version" "db_url" {
  secret      = google_secret_manager_secret.db_url.id
  secret_data = local.db_url
}

resource "google_secret_manager_secret_iam_member" "api_accessor" {
  secret_id = google_secret_manager_secret.db_url.secret_id
  project   = local.project
  role      = "roles/secretmanager.secretAccessor"
  member    = "serviceAccount:${google_service_account.api.email}"
}

resource "google_secret_manager_secret_iam_member" "relay_accessor" {
  secret_id = google_secret_manager_secret.db_url.secret_id
  project   = local.project
  role      = "roles/secretmanager.secretAccessor"
  member    = "serviceAccount:${google_service_account.relay.email}"
}

resource "google_secret_manager_secret_iam_member" "archiver_accessor" {
  secret_id = google_secret_manager_secret.db_url.secret_id
  project   = local.project
  role      = "roles/secretmanager.secretAccessor"
  member    = "serviceAccount:${google_service_account.archiver.email}"
}

locals {
  topic_name    = "${local.prefix}-events"
  dlq_topic     = "${local.prefix}-events-dlq"
  subscription  = "${local.prefix}-events-push"
  dlq_sub       = "${local.prefix}-events-dlq-pull"
}

resource "google_pubsub_topic" "main" {
  name    = local.topic_name
  project = local.project
  labels  = local.labels

  kms_key_name = google_kms_crypto_key.messaging.id
}

resource "google_pubsub_topic" "dlq" {
  name    = local.dlq_topic
  project = local.project
  labels  = local.labels
}

resource "google_pubsub_subscription" "push" {
  name    = local.subscription
  project = local.project
  topic   = google_pubsub_topic.main.name
  labels  = local.labels

  push_config {
    push_endpoint = google_cloudfunctions2_function.processor.url

    oidc_token {
      service_account_email = google_service_account.processor.email
    }
  }

  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.dlq.id
    max_delivery_attempts = 5
  }

  ack_deadline_seconds       = 30
  message_retention_duration = "600s"
  expiration_policy {
    ttl = ""
  }
}

resource "google_pubsub_subscription" "dlq_pull" {
  name    = local.dlq_sub
  project = local.project
  topic   = google_pubsub_topic.dlq.name
  labels  = local.labels

  ack_deadline_seconds = 30
  expiration_policy {
    ttl = ""
  }
}

# IAM bindings
resource "google_pubsub_topic_iam_member" "api_publisher" {
  project = local.project
  topic   = google_pubsub_topic.main.name
  role    = "roles/pubsub.publisher"
  member  = "serviceAccount:${google_service_account.api.email}"
}

resource "google_pubsub_topic_iam_member" "relay_publisher" {
  project = local.project
  topic   = google_pubsub_topic.main.name
  role    = "roles/pubsub.publisher"
  member  = "serviceAccount:${google_service_account.relay.email}"
}

resource "google_pubsub_subscription_iam_member" "processor_subscriber" {
  project      = local.project
  subscription = google_pubsub_subscription.push.name
  role         = "roles/pubsub.subscriber"
  member       = "serviceAccount:${google_service_account.processor.email}"
}

resource "google_pubsub_subscription_iam_member" "dlq_subscriber" {
  project      = local.project
  subscription = google_pubsub_subscription.dlq_pull.name
  role         = "roles/pubsub.subscriber"
  member       = "serviceAccount:${google_service_account.processor.email}"
}

resource "google_cloud_tasks_queue" "rebuild" {
  name    = "${local.prefix}-rebuild-queue"
  project = local.project
  region  = local.region
  labels  = local.labels
}

resource "google_firestore_database" "main" {
  name        = "(default)"
  project     = local.project
  location_id = local.region
  type        = "FIRESTORE_NATIVE"
  labels      = local.labels

  kms_key_name = google_kms_crypto_key.projection.id
}

# Cloud Datastore index for the MediaCache kind
resource "google_datastore_index" "media_cache" {
  project    = local.project
  kind       = "MediaCache"
  collection = "MediaCache"

  properties {
    name      = "namespace"
    direction = "ASCENDING"
  }

  properties {
    name      = "updatedAt"
    direction = "DESCENDING"
  }
}

resource "google_storage_bucket" "audit" {
  name          = "${local.prefix}-audit-logs"
  project       = local.project
  location      = local.region
  force_destroy = true
  labels        = local.labels

  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  versioning {
    enabled = true
  }

  encryption {
    default_kms_key_name = google_kms_crypto_key.audit.id
  }
}

resource "google_storage_bucket_iam_member" "archiver_admin" {
  bucket = google_storage_bucket.audit.name
  role   = "roles/storage.objectAdmin"
  member = "serviceAccount:${google_service_account.archiver.email}"
}

locals {
  jwks_url = "${local.ep}/robot/v1/metadata/jwk/securetoken@system.gserviceaccount.com"
}

resource "google_cloud_run_v2_service" "api" {
  name     = "${local.prefix}-api"
  project  = local.project
  location = local.region
  ingress  = "INGRESS_TRAFFIC_ALL"
  labels   = local.labels

  deletion_protection = false

  template {
    service_account = google_service_account.api.email
    min_instance_count = 2
    max_instance_count = 10

    containers {
      name  = "api"
      image = local.config.api_image

      ports {
        container_port = 8080
      }

      env {
        name  = "DATABASE_URL"
        value = local.db_url
      }
      env {
        name  = "DATASTORE_NAMESPACE"
        value = "${local.prefix}-cache"
      }
      env {
        name  = "FIREBASE_AUTH_JWKS_URL"
        value = local.jwks_url
      }
      env {
        name  = "GOOGLE_CLOUD_PROJECT"
        value = local.project
      }
      env {
        name  = "PUBSUB_TOPIC"
        value = google_pubsub_topic.main.name
      }
      env {
        name  = "GCS_BUCKET"
        value = google_storage_bucket.audit.name
      }
      env {
        name  = "FIRESTORE_DATABASE"
        value = google_firestore_database.main.name
      }
    }

    vpc_access {
      connector = google_vpc_access_connector.main.id
      egress    = "ALL_TRAFFIC"
    }
  }

  traffic {
    type    = "TRAFFIC_TARGET_ALLOCATION_TYPE_LATEST"
    percent = 100
  }
}

