import json,sys
s=json.load(sys.stdin)
ps=s['provider_schemas']
def attrs(prov,name):
  g=ps[prov]['resource_schemas']
  if name not in g: return None
  return sorted(g[name]['block']['attributes'].keys())
for prov in ['registry.terraform.io/hashicorp/google','registry.terraform.io/hashicorp/google-beta']:
  for name in ['google_datastore_index','google_pubsub_topic','google_service_account','google_sql_database','google_sql_user']:
    a=attrs(prov,name)
    if a is not None:
      print(prov.split('/')[-1],name,'| labels=', 'labels' in a,'| attrs=',a)
"

