import json,sys
s=json.load(sys.stdin)
g=s['provider_schemas']['registry.terraform.io/hashicorp/google']['resource_schemas']['google_cloud_run_v2_service']['block']
def walk(b,p=''):
  for a in b.get('attributes',{}): print(p+'.'+a+' (attr)')
  for bt in b.get('block_types',{}):
    sub=b['block_types'][bt]['block']
    print(p+'.'+bt+' BLOCK attrs:',sorted(sub['attributes'].keys()))
    walk(sub,p+'.'+bt)
for bt in g['block_types']:
  if bt in ('template','traffic','scaling'):
    print('### top block',bt)
    walk(g['block_types'][bt]['block'],'template')
" 2>&1 | head -60

