# Global External Application Load Balancer -> Serverless NEG -> Cloud Run API

resource "google_compute_global_address" "lb" {
  name    = "${local.prefix}-lb-ip"
  project = local.project
  labels  = local.labels
}

resource "google_compute_region_network_endpoint_group" "serverless_neg" {
  name                  = "${local.prefix}-api-neg"
  project               = local.project
  region                = local.region
  network_endpoint_type = "SERVERLESS"

  cloud_run {
    service = google_cloud_run_v2_service.api.name
  }
}

resource "google_compute_backend_service" "api" {
  name    = "${local.prefix}-api-backend"
  project = local.project

  backend {
    group = google_compute_region_network_endpoint_group.serverless_neg.id
  }

  enable_cdn = false
}

resource "google_compute_url_map" "api" {
  name            = "${local.prefix}-api-urlmap"
  project         = local.project
  default_service = google_compute_backend_service.api.id
}

resource "google_compute_target_http_proxy" "api" {
  name    = "${local.prefix}-api-proxy"
  project = local.project
  url_map = google_compute_url_map.api.id
}

resource "google_compute_global_forwarding_rule" "api" {
  name       = "${local.prefix}-api-fr"
  project    = local.project
  target     = google_compute_target_http_proxy.api.self_link
  port_range = "80"
  ip_address = google_compute_global_address.lb.address
  labels     = local.labels
}

locals {
  lb_ip  = google_compute_global_address.lb.address
  lb_url = "http://${local.lb_ip}"
}

locals {
  ingress_cidr = "10.10.0.0/20"
  private_cidr = "10.10.32.0/20"
  labels       = { "mediapulse_deployment" = local.prefix }
}

resource "google_compute_network" "vpc" {
  name                    = "${local.prefix}-vpc"
  auto_create_subnetworks = false
  project                 = local.project
}

resource "google_compute_subnetwork" "ingress" {
  name                     = "${local.prefix}-ingress-subnet"
  project                  = local.project
  region                   = local.region
  network                  = google_compute_network.vpc.id
  ip_cidr_range            = local.ingress_cidr
  private_ip_google_access = false
}

resource "google_compute_subnetwork" "private" {
  name                     = "${local.prefix}-private-subnet"
  project                  = local.project
  region                   = local.region
  network                  = google_compute_network.vpc.id
  ip_cidr_range            = local.private_cidr
  private_ip_google_access = true
}

resource "google_compute_firewall" "ingress_http" {
  name    = "${local.prefix}-allow-http"
  project = local.project
  network = google_compute_network.vpc.id

  allow {
    protocol = "tcp"
    ports    = ["80", "8080"]
  }
  source_ranges = ["0.0.0.0/0"]
  target_tags   = ["mediapulse-ingress", "mediapulse-api"]
}

resource "google_compute_firewall" "db_internal" {
  name    = "${local.prefix}-allow-db-internal"
  project = local.project
  network = google_compute_network.vpc.id

  allow {
    protocol = "tcp"
    ports    = ["5432"]
  }
  source_ranges = [local.ingress_cidr, local.private_cidr]
  target_tags   = ["mediapulse-db"]
}

resource "google_sql_database_instance" "main" {
  name                = "${local.prefix}-db"
  project             = local.project
  region              = local.region
  database_version    = "POSTGRES_15"
  deletion_protection = false
  encryption_key_name  = google_kms_crypto_key.database.id

  settings {
    tier              = "db-custom-2-4096"
    availability_type = "ZONAL"
    user_labels       = local.labels

    ip_configuration {
      ipv4_enabled = true
    }
  }
}

resource "google_sql_database" "db" {
  name     = local.db_name
  project  = local.project
  instance = google_sql_database_instance.main.name
}

resource "google_sql_user" "user" {
  name     = local.db_user
  project  = local.project
  instance = google_sql_database_instance.main.name
  password = local.db_pass
}

locals {
  db_host = google_sql_database_instance.main.public_ip_address
  db_url  = "postgresql://${local.db_user}:${urlencode(local.db_pass)}@${local.db_host}:5432/${local.db_name}?sslmode=disable"
}

